import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"姤","description":"东坡易传 - 姤","frontmatter":{"title":"姤","description":"东坡易传 - 姤"},"headers":[],"relativePath":"zh/classics/dongpo/045.md","filePath":"zh/classics/dongpo/045.md"}'),o={name:"zh/classics/dongpo/045.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><p>“姤”，女壯，勿用取女。</p><p>《彖》曰：“姤”，遇也，柔遇剛也。“勿用取女”，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義大矣哉！</p><p>“姤”者，所遇而合，無適意之謂也。故其女“不可與長”。“姤”者，“乾”之末，“坤”之始也，故曰“天地相遇”。以四時言之，則建午之月，“品物鹹章”之際也。《易》曰：“萬物相見乎‘離’。” “剛”者，二也；“中正”者，五也。陰之長，自九二之亡而後爲“遯”，始無臣也；自九五之亡而後爲“剝”，始無君也。“姤”之世，上有君、下有臣，君子之慾有爲，無所不可。故曰：“剛遇中正，天下大行也。”</p><p>象曰：天下有風，“姤”；後以施命誥四方。</p><p>初六：繫於金柅，貞吉；有攸往，見兇。羸豕孚蹢躅。象曰：“繫於金柅”，柔道牽也。</p><p>剛而能止物者，謂之“金柅”，九二是也。初六之勢，足以兼獲五陽，然其始遇而合者，九二也。既合於二，若舍而之他①，則終身無所容矣，故以系二而貞爲吉。有所往見爲兇，初六者，“羸豕”也。雖“羸”而不可信者，以權在焉，以其“羸”而信之，則“蹢躅”而不可制矣。</p><p>【校注】 ① 既合於二，若舍而之他：《蘇氏易傳》作“既合不貞，又舍而之他”，誤。</p><p>九二：包有魚，無咎；不利賓。象曰：“包有魚”，義不及賓也。</p><p>“魚”者，初六也；“包”者，魚之所不能脫也；“賓”者，九四也。“姤”者，主求民之時，非民求主之時也，故近而先者得之，遠而後者不得也。不論其應與否也，嫌其若有咎，故曰“無咎”。</p><p>九三：臀無膚，其行次且，厲；無大咎。象曰：“其行次且”，行未牽也。</p><p>以“姤”之初六爲“夬”之上六，則“姤”之九三，“夬”之九四也，故其《象》同。九三之所謂臀者，初六；初六剝陽而進者也，處衆陽之間而同體者，有剝陽之陰，宜其“次且”而不安也。“夬”之九四下牽初九之羊，故有“聰不明”之咎。而九三無是也，故雖危無孔大咎，而《象》曰“行未牽也”。</p><p>九四：包無魚，起兇。象曰：“無魚”之“兇”，遠民也。</p><p>既已失民，起而爭之則“兇”。</p><p>九五：以杞包瓜，含章，有隕自天。象曰：九五“含章”，中正也；“有隕自天”，志不捨命也。</p><p>“金柅”也，“包”也，“杞”也，皆九二也；“豕”也，“魚”也，“瓜”也，皆初六也。“杞”，枸杞也，木之至痺者也。“包瓜”者，籠而有之也。瓜之爲物，得所附而後止；不得所附，則攀援而求，無所不至。幸而遇喬木，則雖欲抑之不可得矣，故授之以杞，則杞能籠而有之。杞之所至，瓜之所及也。九五者，“姤”之主也；知初六之勢將至於剝盡而後止，故授之以九二。九二之所至，初六之所及也。“姤”者，陰長之卦；而九五以至陽而勝之，故曰“含章”。凡陰中之陽爲“章”，陰長而消陽，天之命也；有以勝之，人之志也。君子不以命廢志，故九五之志堅，則必有自天而隕者，言人之至者，天不能勝也。</p><p>上九：姤其角，吝；無咎。象曰：“姤其角”，上窮吝也。</p><p>剛之上窮者，“角”也。“姤其角”，以是爲“姤”也。以角爲“姤”，物之所不樂遇也；小人雖不能合，而君子亦無自入焉。故“吝，無咎”。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
